/* =========================================================
   Puff · 长夜＆机械之心 × 樱花晨光玻璃（方角设计+心电图）『作者：长夜何其多』
   ========================================================= */

/* 1. 全局变量与方角设定 */
.off-app {
  --off-list-radius: 0px;
  --off-list-ava-size: 52px;
  --off-pink: #efb8cb;
  --off-pink-light: #fce6ed;
  --off-glass: rgba(255, 255, 255, 0.62);
  --off-glass-heavy: rgba(255, 255, 255, 0.78);
  --off-glass-border: rgba(255, 255, 255, 0.82);
  --off-glass-shadow: 0 8px 30px rgba(125, 88, 103, 0.055), inset 0 1px 0 rgba(255, 255, 255, 0.92);
}

/* 强制所有元素变方角 */
.off-app .off-list,
.off-app .off-list-ava,
.off-app.off-app-session .off-passage-sheet,
.off-app .off-compose-bar,
.off-inbox-filter,
.off-inbox-filter button,
.off-app .off-thinking-chip {
  border-radius: 0 !important;
}

/* 2. 核心注入：背景图铺满 */
.off-app.off-app-session .off-stage,
.off-app.off-app-session .off-stage.has-bg {
  background-image: url('https://picui.ogmua.cn/s1/2026/11/08/6aefd141b1ab1.webp') !important;
  background-size: cover !important;
  background-position: center !important;
  background-attachment: fixed !important;
}

/* 3. 筛选器（方角） */
.off-inbox-filter {
  background: rgba(255, 255, 255, 0.45) !important;
  border: 1px solid rgba(255, 255, 255, 0.72) !important;
  backdrop-filter: blur(20px) saturate(125%) !important;
  -webkit-backdrop-filter: blur(20px) saturate(125%) !important;
}
.off-inbox-filter button { color: #a69a9f !important; background: transparent !important; }
.off-inbox-filter button.on {
  color: #fff !important;
  background: linear-gradient(135deg, #f5c9d9, #efb5ca) !important;
  box-shadow: 0 4px 12px rgba(225, 164, 186, 0.18) !important;
}

/* 4. 入口列表（方角玻璃） */
.off-app:not(.off-app-session) .off-list {
  background: linear-gradient(145deg, rgba(255, 247, 250, 0.95), rgba(252, 249, 250, 0.90)) !important;
  border: 1px solid var(--off-glass-border) !important;
  backdrop-filter: blur(28px) saturate(125%) !important;
  -webkit-backdrop-filter: blur(28px) saturate(125%) !important;
  box-shadow: var(--off-glass-shadow) !important;
  overflow: hidden !important;
}
.off-list-btn { border-bottom: 1px solid rgba(255, 255, 255, 0.5) !important; }
.off-list-btn:hover { background: rgba(245, 205, 220, 0.09) !important; }
.off-list-body strong { color: #4a4347 !important; font-weight: 600 !important; }
.off-list-body span { color: #91878b !important; }

/* =========================================================
   5. 顶栏 + 顶部心电图 + 跑动爱心
   ========================================================= */
.off-app.off-app-session .off-stage-head {
  background: rgba(255, 251, 253, 0.58) !important;
  backdrop-filter: blur(26px) saturate(125%) !important;
  -webkit-backdrop-filter: blur(26px) saturate(125%) !important;
  border-bottom: none !important;
  position: relative !important;
  overflow: visible !important;
  z-index: 10 !important;
}

/* 顶部粉线 */
.off-app.off-app-session .off-stage-head::after {
  content: "" !important;
  position: absolute !important;
  bottom: -16px !important; left: 0 !important; right: 0 !important;
  height: 16px !important;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 20" preserveAspectRatio="none"><path d="M0 15 L10 15 L15 15 L18 5 L22 18 L25 10 L28 15 L40 15 L43 12 L46 15 L60 15 L63 5 L67 18 L70 10 L73 15 L85 15 L88 12 L91 15 L100 15" fill="none" stroke="%23ec7ca0" stroke-width="1.5" opacity="0.9"/></svg>') !important;
  background-size: 120px 16px !important; background-repeat: repeat-x !important;
  animation: ecg-flow 3s linear infinite !important; z-index: 99 !important;
}
/* 跑动粉心 */
.off-app.off-app-session .off-stage-head::before {
  content: '♥' !important;
  position: absolute !important;
  bottom: -23px !important; left: 10% !important;
  font-size: 16px !important;
  color: #ec7ca0 !important; text-shadow: 0 0 6px rgba(236, 124, 160, 0.9) !important; 
  z-index: 999 !important; pointer-events: none !important;
  animation: heart-walk 4s ease-in-out infinite alternate !important;
}

/* 6. 消息卡片（粉白 vs 纯白） */
.off-app.off-app-session {
  --off-card-user: linear-gradient(135deg, rgba(255, 231, 239, 0.8), rgba(255, 247, 250, 0.8));
  --off-card-peer: rgba(255, 255, 255, 0.65);
  --off-card-border: rgba(255, 255, 255, 0.82);
  --off-card-shadow: 0 8px 30px rgba(110, 75, 90, 0.055), inset 0 1px 0 rgba(255, 255, 255, 0.9);
  --off-prose-font: var(--display), "Noto Serif SC", "Source Han Serif SC", Georgia, serif;
}
.off-app.off-app-session .off-passage-sheet {
  background: var(--off-card-peer) !important;
  border: 1px solid var(--off-card-border) !important;
  box-shadow: var(--off-card-shadow) !important;
  backdrop-filter: blur(24px) saturate(125%) !important;
  -webkit-backdrop-filter: blur(24px) saturate(125%) !important;
}
.off-app.off-app-session .off-passage.is-me .off-passage-sheet {
  background: var(--off-card-user) !important;
  border-color: rgba(242, 191, 208, 0.38) !important;
}
.off-app.off-app-session .off-prose-para,
.off-app.off-app-session .off-prose-narr,
.off-app.off-app-session .off-prose-plain,
.off-app.off-app-session .off-prose-dial {
  color: #4a4347 !important;
  line-height: 1.85 !important;
  font-size: 14.5px !important;
}

/* 7. 底栏 + 底部心电图 */
.off-app.off-app-session .off-stage-dock {
  background: rgba(255, 250, 252, 0.70) !important;
  backdrop-filter: blur(28px) saturate(130%) !important;
  -webkit-backdrop-filter: blur(28px) saturate(130%) !important;
  border-top: none !important;
  position: relative !important;
  overflow: visible !important;
  z-index: 10 !important;
  padding-top: 20px !important;
}
/* 底部粉线 */
.off-app.off-app-session .off-stage-dock::before {
  content: "" !important;
  position: absolute !important;
  top: -16px !important; left: 0 !important; right: 0 !important;
  height: 16px !important;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 20" preserveAspectRatio="none"><path d="M0 15 L10 15 L15 15 L18 5 L22 18 L25 10 L28 15 L40 15 L43 12 L46 15 L60 15 L63 5 L67 18 L70 10 L73 15 L85 15 L88 12 L91 15 L100 15" fill="none" stroke="%23ec7ca0" stroke-width="1.5" opacity="0.9"/></svg>') !important;
  background-size: 120px 16px !important; background-repeat: repeat-x !important;
  animation: ecg-flow-reverse 3s linear infinite !important; z-index: 99 !important;
}

/* 8. 输入框（方角） */
.off-app .off-compose-bar {
  background: rgba(255, 255, 255, 0.70) !important;
  border: 1px solid rgba(255, 255, 255, 0.88) !important;
  backdrop-filter: blur(24px) saturate(125%) !important;
  box-shadow: 0 5px 20px rgba(110, 75, 90, 0.055) !important;
}
.off-compose-send {
  background: linear-gradient(135deg, #f4c7d8, #edb4ca) !important;
  color: #fff !important;
}

/* 动画 */
@keyframes ecg-flow { 0% { background-position: 0 0; } 100% { background-position: -120px 0; } }
@keyframes ecg-flow-reverse { 0% { background-position: 0 0; } 100% { background-position: 120px 0; } }
@keyframes heart-walk {
  0% { left: 4%; transform: translateY(0) scale(1); }
  30% { transform: translateY(-4px) scale(1.15); } 
  60% { transform: translateY(0) scale(1); }
  80% { transform: translateY(-4px) scale(1.15); } 
  100% { left: 96%; transform: translateY(0) scale(1); }
}
